import{_ as d,o as e,c as o,ag as a}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"随机码元发生器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.2.0-alpha/modules/random_symbols/index.md","filePath":"v0.2.0-alpha/modules/random_symbols/index.md"}'),r={name:"v0.2.0-alpha/modules/random_symbols/index.md"};function c(l,t,n,h,i,s){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="随机码元发生器" tabindex="-1">随机码元发生器 <a class="header-anchor" href="#随机码元发生器" aria-label="Permalink to &quot;随机码元发生器&quot;">​</a></h1><p>适用：v0.2.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>random_symbols</code> · 模块定义版本：4</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>生成未打包的离散码元索引，每个输出 item 表示一个码元。它为映射和判决实验提供随机输入，帮助理解索引、星座点和复数波形之间的关系。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>随机码元发生器.out → 符号映射器.in</code>，再接星座观察或信道。源与映射器须使用相容的码元数量，不能把码元索引直接当作模拟幅度信号。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输出</td><td><code>out</code>（码元输出）</td><td><code>symbol_u8</code></td><td>索引；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>随机区间的最小索引包含在内，最大索引不包含在内，且两端必须落在当前星座的 M 个编号中。缩小区间可只激励部分码元，便于观察它们对应的点。</p><p>星座点表在本模块中确定码元定义和数量，不会把输出自动变成复数坐标。D 表示映射后每个码元对应的连续坐标数；源输出仍是每码元一个索引。固定种子适合重复对照起始序列。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>码元率（符号/s）<br><code>sample_rate_hz</code></td><td><code>4096</code></td><td>范围 1 至 1000000；Master 支持 1–1000000 Hz，可输入小数；下限保证单个采样周期不超过 1 秒。理想码元时钟，每个未打包索引对应一个码元；映射器每个码元输出 D 个连续复数坐标。</td><td>重新准备</td></tr><tr><td>星座模式<br><code>constellation</code></td><td><code>qpsk</code></td><td>BPSK (<code>bpsk</code>)；QPSK (<code>qpsk</code>)；16QAM (<code>qam16</code>)；自定义 (<code>custom</code>)；预设按 I 后 Q 升序编号；BPSK 为 -1、+1，QPSK 除以 √2，16QAM 的 ±1/±3 网格除以 √10。自定义点表按输入顺序从 0 编号，可另选归一化方式。</td><td>重新准备</td></tr><tr><td>按码元编号排列的点表实部<br><code>points_real</code></td><td><code>[-0.7071067811865475, -0.7071067811865475, 0.7071067811865475, 0.7071067811865475]</code></td><td>按字段类型填写，见下文说明</td><td>重新准备</td></tr><tr><td>按码元编号排列的点表虚部<br><code>points_imag</code></td><td><code>[-0.7071067811865475, 0.7071067811865475, -0.7071067811865475, 0.7071067811865475]</code></td><td>按字段类型填写，见下文说明</td><td>重新准备</td></tr><tr><td>点表归一化<br><code>normalization</code></td><td><code>none</code></td><td>保留原坐标 (<code>none</code>)；平均幅度为 1 (<code>amplitude</code>)；平均功率为 1 (<code>power</code>)</td><td>重新准备</td></tr><tr><td>最小索引（包含）<br><code>minimum</code></td><td><code>0</code></td><td>范围 0 至 255</td><td>重新准备</td></tr><tr><td>最大索引（不包含）<br><code>maximum</code></td><td><code>4</code></td><td>范围 0 至 256</td><td>重新准备</td></tr><tr><td>种子模式<br><code>seed_mode</code></td><td><code>fixed</code></td><td>固定 (<code>fixed</code>)；系统时间 (<code>system_time</code>)</td><td>重新准备</td></tr><tr><td>随机种子<br><code>seed</code></td><td><code>0</code></td><td>范围 0 至 2147483646</td><td>重新准备</td></tr><tr><td>每个码元的连续复数坐标数 D<br><code>dimensionality</code></td><td><code>1</code></td><td>范围 1 至 1024；本版 D 支持 1–1024；自定义点表按码元顺序连续填写 M×D 个复数坐标，预设为 D=1。</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><p>源的时钟、索引区间和码元定义改变后重新准备，并核对下游映射／判决设置。重新准备会开始新的运行时间基准；已有通道数据不应按新草稿的星座重新解释。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="qpsk-映射、判决与理想信道" tabindex="-1">QPSK 映射、判决与理想信道 <a class="header-anchor" href="#qpsk-映射、判决与理想信道" aria-label="Permalink to &quot;QPSK 映射、判决与理想信道&quot;">​</a></h3><p><a href="../../../downloads/v0.2.0-alpha/qpsk-channel.cnsproj" download>下载 qpsk-channel.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>QPSK 映射、判决与理想信道</p><ul><li>直接判决逐码元一致。理想信道仍保留 GNU 原生 3 点前视，不能将信道两端同索引当作已对齐。</li></ul><p>QPSK 示例从随机索引进入映射器，再分别走直接判决和信道判决分支。观察源输出中的离散索引，再看映射器输出的星座点；直接判决应逐码元恢复原索引。整组为本机数字基带仿真。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>为什么看不到连续正弦载波？</strong> 这里生成的是离散索引，波形坐标由映射器产生，载波和脉冲成形属于不同处理。</p><p><strong>只出现部分星座点？</strong> 先检查随机区间，再考虑有限样本中是否尚未覆盖所有码元。</p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/09-symbols/">09 码元、星座与判决</a></li></ul>',28)])])}const b=d(r,[["render",c]]);export{m as __pageData,b as default};
